<?php if (!$camps): ?><div class="empty-state"><span class="empty-icon" aria-hidden="true">⚑</span><h3><?= $user['role']==='main_staff' ? 'เริ่มต้นค่ายแรกของคุณ' : 'ยังไม่มีค่ายที่คุณเข้าถึงได้' ?></h3><p><?= $user['role']==='main_staff' ? 'สร้างข้อมูลค่าย แล้วเพิ่มบัญชีสตาฟเพื่อเตรียมทีมงาน' : 'เมื่อสตาฟหลักเพิ่มคุณเข้าค่าย ข้อมูลจะแสดงที่นี่' ?></p><?php if ($user['role']==='main_staff'): ?><a class="button primary" href="<?= e(url(($title??'')==='ตั้งค่าค่าย'?'camp-edit':'camp-settings')) ?>">ตั้งค่าค่าย / สร้างค่าย</a><?php endif ?></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>ชื่อค่าย</th><th>วันที่จัดค่าย</th><th>สถานะ</th><th><span class="sr-only">การดำเนินการ</span></th></tr></thead><tbody><?php foreach ($camps as $camp): ?><tr><td><a class="table-title" href="<?= e(url('camp',['id'=>$camp['id']])) ?>"><?= e($camp['name']) ?></a><small>รหัสค่าย #<?= e($camp['id']) ?></small></td><td><?= e($camp['start_date']) ?> <span class="muted">ถึง</span> <?= e($camp['end_date']) ?></td><td><span class="badge <?= e($camp['status']) ?>"><?= e(statuses()[$camp['status']]) ?></span></td><td><a class="text-link" href="<?= e(url('camp',['id'=>$camp['id']])) ?>">ดูค่าย →</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
